"""Independent checker for PLAN objects (testing only, not shipped)."""


def verify_plan(plan, links, link_caps, period, envelope, parts, rdem, err=print):
    ok = True

    def bad(msg):
        nonlocal ok
        ok = False
        err('PLAN INVALID: ' + msg)

    if set(plan.keys()) != {'trees', 'routes', 'recipes'}:
        bad('plan keys %r' % (sorted(plan.keys()),))
        return False
    trees = plan['trees']
    routes = plan['routes']
    recipes = plan['recipes']
    C = set(parts)
    D = sum(rdem[v] for v in parts)
    if len(trees) > 8192:
        bad('too many trees %d' % len(trees))
    if len(routes) > 32768:
        bad('too many routes %d' % len(routes))
    if len(recipes) > 65536:
        bad('too many recipes %d' % len(recipes))
    # trees
    per_root = {}
    L = {}
    for rec in trees:
        if not (isinstance(rec, list) and len(rec) == 3):
            bad('tree record shape %r' % (rec,))
            return False
        root, count, edges = rec
        if root not in C:
            bad('root %r not participant' % (root,))
        if not isinstance(count, int) or count <= 0 or count > D:
            bad('count %r' % (count,))
        per_root[root] = per_root.get(root, 0) + count
        seen = set()
        indeg = {v: 0 for v in C}
        adj = {v: [] for v in C}
        if len(edges) != len(C) - 1:
            bad('tree %r has %d edges, |C|-1=%d' % (root, len(edges), len(C) - 1))
        for e in edges:
            if not (isinstance(e, list) and len(e) == 2):
                bad('edge shape %r' % (e,))
                return False
            u, v = e
            if u not in C or v not in C or u == v:
                bad('edge endpoints %r' % (e,))
            if (u, v) in seen:
                bad('duplicate edge %r' % (e,))
            seen.add((u, v))
            indeg[v] = indeg.get(v, 0) + 1
            adj[u].append(v)
            L[(u, v)] = L.get((u, v), 0) + count
        if indeg.get(root, 0) != 0:
            bad('root indegree %r' % (root,))
        for v in C:
            if v != root and indeg[v] != 1:
                bad('indegree of %r is %r' % (v, indeg[v]))
        # reachability
        seen_nodes = {root}
        stack = [root]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v not in seen_nodes:
                    seen_nodes.add(v)
                    stack.append(v)
        if seen_nodes != C:
            bad('tree from %r does not span C' % (root,))
    for v in C:
        want = rdem[v]
        got = per_root.get(v, 0)
        if got != want:
            bad('root %r total count %r != demand %r' % (v, got, want))
    # recipes: evaluate each node to (start, end) walk; check acyclic + typing
    n_nodes = len(recipes)
    endpoint = [None] * n_nodes
    state = [0] * n_nodes  # 0 unvisited, 1 in progress, 2 done
    expanded = [None] * n_nodes

    def resolve(i, depth=0):
        if state[i] == 2:
            return endpoint[i]
        if state[i] == 1:
            bad('recipe cycle at %d' % i)
            return None
        state[i] = 1
        node = recipes[i]
        if not isinstance(node, list) or len(node) not in (2, 3):
            bad('recipe node shape %r' % (node,))
            state[i] = 2
            return None
        if node[0] == 0:
            if len(node) != 3:
                bad('leaf shape %r' % (node,))
            lid, d = node[1], node[2]
            if not (0 <= lid < len(links)):
                bad('leaf link %r' % (lid,))
                state[i] = 2
                return None
            if d not in (0, 1):
                bad('leaf dir %r' % (d,))
            u, v = links[lid]
            if d == 1:
                u, v = v, u
            endpoint[i] = (u, v)
            expanded[i] = [(u, v)]
        elif node[0] == 1:
            if len(node) != 3:
                bad('cat shape %r' % (node,))
            l, r = node[1], node[2]
            if not (isinstance(l, int) and 0 <= l < n_nodes):
                bad('cat left ref %r' % (l,))
                state[i] = 2
                return None
            if not (isinstance(r, int) and 0 <= r < n_nodes):
                bad('cat right ref %r' % (r,))
                state[i] = 2
                return None
            a = resolve(l, depth + 1)
            b = resolve(r, depth + 1)
            if a is None or b is None:
                state[i] = 2
                return None
            if a[1] != b[0]:
                bad('concat mismatch %r %r at %d' % (a, b, i))
            elif a[1] in C:
                bad('concat at participant %r node %d' % (a[1], i))
            endpoint[i] = (a[0], b[1])
            expanded[i] = expanded[l] + expanded[r]
        else:
            bad('recipe tag %r' % (node[0],))
        state[i] = 2
        return endpoint[i]

    import sys
    sys.setrecursionlimit(100000)
    for i in range(n_nodes):
        resolve(i)
    if not ok:
        return False
    # routes
    per_pair = {}
    for rec in routes:
        if not (isinstance(rec, list) and len(rec) == 4):
            bad('route shape %r' % (rec,))
            return False
        u, v, count, rid = rec
        if u not in C or v not in C or u == v:
            bad('route endpoints %r' % (rec,))
        if not isinstance(count, int) or count <= 0 or count > D:
            bad('route count %r' % (count,))
        if not (isinstance(rid, int) and 0 <= rid < n_nodes):
            bad('route recipe %r' % (rid,))
            continue
        ep = endpoint[rid]
        if ep is None:
            bad('route recipe %d unresolved' % rid)
        elif ep != (u, v):
            bad('route %r recipe walk %r' % (rec, ep))
        per_pair[(u, v)] = per_pair.get((u, v), 0) + count
    for k, want in L.items():
        if per_pair.get(k, 0) != want:
            bad('pair %r routes %r != L %r' % (k, per_pair.get(k, 0), want))
    for k, got in per_pair.items():
        if k not in L and got != 0:
            bad('pair %r routes %r but L=0' % (k, got))
    if not ok:
        return False
    # physical load
    cap = {}
    for lid, (u, v) in enumerate(links):
        c = period * envelope.get(lid, 0)
        cap[(lid, 0)] = c
        cap[(lid, 1)] = c
    load = {}
    for rec in routes:
        u, v, count, rid = rec
        for (a, b) in expanded[rid]:
            key = None
            for lid, (pu, pv) in enumerate(links):
                if pu == a and pv == b:
                    key = (lid, 0)
                    break
                if pv == a and pu == b:
                    key = (lid, 1)
                    break
            if key is None:
                bad('walk arc %r is not a link' % ((a, b),))
                return False
            load[key] = load.get(key, 0) + count
    for key, val in load.items():
        if val > cap.get(key, 0):
            bad('link %r load %r > capacity %r' % (key, val, cap.get(key, 0)))
    return ok
